class Solution {
public:
    vector<string> printVertically(string s) {
        vector<string> words;
        stringstream ss(s);
        string w;
        while (ss >> w) words.push_back(w);
        size_t m = 0;
        for (auto& x : words) m = max(m, x.size());
        vector<string> res;
        for (size_t c = 0; c < m; c++) {
            string col;
            for (auto& x : words) col += c < x.size() ? x[c] : ' ';
            while (!col.empty() && col.back() == ' ') col.pop_back();
            res.push_back(col);
        }
        return res;
    }
};

