var printVertically = function(s) {
    const words = s.split(' ');
    const m = Math.max(...words.map(w => w.length));
    const res = [];
    for (let c = 0; c < m; c++) {
        let col = '';
        for (const w of words) col += c < w.length ? w[c] : ' ';
        res.push(col.replace(/ +$/, ''));
    }
    return res;
};

