class Solution:
    def printVertically(self, s: str) -> List[str]:
        cols = []
        wi = pos = 0
        for ch in s:
            if ch == ' ':
                wi += 1
                pos = 0
            else:
                if pos == len(cols):
                    cols.append([' '] * wi)
                elif len(cols[pos]) < wi:
                    cols[pos].extend(' ' * (wi - len(cols[pos])))
                cols[pos].append(ch)
                pos += 1
        return [''.join(c).rstrip() for c in cols]

