class Solution {
public:
    vector<string> printVertically(string s) {
        vector<string> cols;
        int wi = 0, pos = 0;
        for (char ch : s) {
            if (ch == ' ') { wi++; pos = 0; continue; }
            if ((int)cols.size() == pos) cols.push_back(string(wi, ' '));
            else if ((int)cols[pos].size() < wi) cols[pos].append(wi - cols[pos].size(), ' ');
            cols[pos] += ch;
            pos++;
        }
        for (auto& c : cols)
            while (!c.empty() && c.back() == ' ') c.pop_back();
        return cols;
    }
};

