class Solution {
    public List<String> printVertically(String s) {
        List<StringBuilder> cols = new ArrayList<>();
        int wi = 0, pos = 0;
        for (char ch : s.toCharArray()) {
            if (ch == ' ') { wi++; pos = 0; continue; }
            if (cols.size() == pos) {
                StringBuilder b = new StringBuilder();
                for (int i = 0; i < wi; i++) b.append(' ');
                cols.add(b);
            } else {
                StringBuilder b = cols.get(pos);
                while (b.length() < wi) b.append(' ');
            }
            cols.get(pos).append(ch);
            pos++;
        }
        List<String> res = new ArrayList<>();
        for (StringBuilder b : cols) {
            int end = b.length();
            while (end > 0 && b.charAt(end - 1) == ' ') end--;
            res.add(b.substring(0, end));
        }
        return res;
    }
}

