var printVertically = function(s) {
    const cols = [];
    let wi = 0, pos = 0;
    for (const ch of s) {
        if (ch === ' ') { wi++; pos = 0; continue; }
        if (cols.length === pos) cols.push(' '.repeat(wi));
        else if (cols[pos].length < wi) cols[pos] += ' '.repeat(wi - cols[pos].length);
        cols[pos] += ch;
        pos++;
    }
    return cols.map(c => c.replace(/ +$/, ''));
};
